function markTestsGenerated(ctx) {
    try {
        ctx.tracker.addLabel(ctx.ticketKey, LABELS.AI_TESTS_GENERATED);
        console.log('✅ Added label "' + LABELS.AI_TESTS_GENERATED + '" to ' + ctx.ticketKey);
