    if (!shouldProbeThreadLimit(recommendation, hasOpenIssues, allowApproveWithSuggestions, prNumber, repoInfo, maxThreadLimit)) return false;
    return threadCountExceedsLimit(scm, prNumber, maxThreadLimit);
