    '\u26A0\uFE0F **Downgraded from \uD83D\uDEA8 BLOCKING (gh-1053)** \u2014 this finding asserts what an ' +
    'external spec/reference says without quoting the exact source ' +
    '(file:line or doc URL) read during the review. Please confirm against ' +
    'the cited source; if confirmed, re-raise as BLOCKING with a ' +
    'verifiable citation.';

function downgradeBody(body) {
    var text = String(body || '');
    var out = text.replace(/\uD83D\uDEA8/g, '\u26A0\uFE0F');
    out = out.replace(/(^|[^\w-])BLOCKING\b/gi, '$1IMPORTANT');
