    test('AC3: uncited external-spec claim is classified NON-BLOCKING even with a 🚨 marker', function () {
        var body = '🚨 BLOCKING: the spec says only *_MAX_TOKENS and *_TOKEN_LIMIT are exempt — this PR exempts more.';
