    /\bper\s+(?:the\s+)?(?:spec|specification|specs|docs?|documentation|reference|standard)\b/i,
    /\b(?:the\s+)?(?:java|reference\s+implementation|upstream|official\s+docs?|api\s+docs?)\s+(?:says|states|requires|uses|does|exempts|allows|defines|expects|supports|forbids)\b/i,
